// spec: specs/warehouse-map.md §6
// seed: tests/seed.admin.spec.ts
// #1f62ca42 — «החזרה לספק» на карте склада: остаток «ללא מקום» (был 400 / 23514) и из места (AC2).
// ⚠️ Возврат поставщику и записи журнала НЕОБРАТИМЫ — данные минимальные:
//   U «QA-AUTO-1f62-U-<ts>» — 3 шт. «ללא מקום» → вернуть 1, затем 2;
//   L «QA-AUTO-1f62-L-<ts>» — привязан к ПУСТОМУ месту (C-04 / C-01), 2 шт. → вернуть 1.
// Не запускать одновременно с inventory-lifecycle / order-lifecycle / cart-checkout.
// #9301886c (14.10): строка окна = товар + место; у двух строк одного товара одинаковый aria-label «כמות ל<שם>»,
//   поэтому поле кол-ва ищется внутри строки (qtyOf). Новые сценарии окна — supplier-return-rows.spec.ts.
// afterAll: «הסרה מהמקום» у L, удаление U и L, место снова «ריק».
import { test, expect, Page, Browser, Response } from '@playwright/test';
import * as path from 'path';

const ADMIN = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const U = `QA-AUTO-1f62-U-${TS}`;
const L = `QA-AUTO-1f62-L-${TS}`;
const REF = (s: string) => `QA-AUTO-1f62-${TS}-${s}`;
const CANDIDATE_PLACES = ['C-04', 'C-01']; // C-03 занят тестами inventory
const NO_PLACE = 'ללא מקום — לשיוך בהמשך';

const created = new Set<string>();
let usedPlace: string | null = null;

// ---------- каталог ----------
const qtyBtn = (page: Page, p: string) => page.getByRole('button', { name: `קליטת מלאי — ${p}`, exact: true });
const locBtn = (page: Page, p: string) => page.getByRole('button', { name: `מיקום במחסן — ${p}`, exact: true });
const row = (page: Page, p: string) => qtyBtn(page, p).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function findProduct(page: Page, p: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(p);
  await expect(qtyBtn(page, p).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
}

async function expectStock(page: Page, p: string, n: number) {
  await findProduct(page, p);
  await expect(qtyBtn(page, p)).toHaveText(String(n), { timeout: 15_000 });
}

async function createProduct(page: Page, p: string, sku: string) {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(p);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(sku);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
  created.add(p);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
}

/** «קליטת מלאי» кликом по числу «במלאי»; code=null — проверяем, что выбрано «ללא מקום». */
async function receive(page: Page, p: string, qty: number, code: string | null) {
  await findProduct(page, p);
  await qtyBtn(page, p).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  const select = dlg.getByRole('combobox', { name: 'מקום היעד' });
  if (code) await expect(select.locator('option:checked')).toContainText(`(${code})`);
  else await expect(select.locator('option:checked')).toHaveText(NO_PLACE);
  await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill(String(qty));
  await dlg.getByRole('button', { name: 'הוספה' }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
  await expectStock(page, p, qty);
}

// ---------- карта ----------
const side = (page: Page) =>
  page.getByRole('complementary').filter({ has: page.getByRole('button', { name: 'כיווץ סרגל האחסון' }) });

async function openMap(page: Page) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole('tablist', { name: 'קומות המחסן' })).toBeVisible({ timeout: 30_000 });
}

/** «קומה 1» → «ארון X» → полка с кодом. Возвращает подпись полки (строки) — имя первое, «ריק» последнее если пусто. */
async function openPlace(page: Page, code: string): Promise<string[]> {
  await openMap(page);
  await page.getByRole('tablist', { name: 'קומות המחסן' }).getByRole('tab', { name: 'קומה 1' }).click();
  await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
  await side(page).getByRole('button', { name: new RegExp(`^ארון ${code[0]}`) }).click();
  await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
  const shelf = side(page).getByRole('button', { name: new RegExp(`${code}(?!\\d)`) }).first();
  await expect(shelf).toBeVisible();
  const label = (await shelf.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
  await shelf.click();
  await expect(side(page).getByRole('heading', { name: 'תכולת המדף' })).toBeVisible();
  return label;
}

/** Первое пустое место из CANDIDATE_PLACES (подпись полки заканчивается на «ריק»). */
async function pickEmptyPlace(page: Page): Promise<{ code: string; shelf: string } | null> {
  for (const code of CANDIDATE_PLACES) {
    const label = await openPlace(page, code);
    if (label[label.length - 1] === 'ריק') return { code, shelf: label[0] };
  }
  return null;
}

async function bindPlace(page: Page, p: string, code: string, shelfName: string) {
  await findProduct(page, p);
  await locBtn(page, p).first().click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מיקום במחסן' })).toBeVisible();
  await dlg.getByRole('tab', { name: 'קומה 1' }).click();
  await expect(dlg.getByText('בחרו פריט אחסון')).toBeVisible();
  await dlg.getByRole('button', { name: `ארון ${code[0]}`, exact: true }).click();
  await expect(dlg.getByText(`בחרו מדף ב«ארון ${code[0]}»`)).toBeVisible();
  await dlg.getByRole('button', { name: shelfName, exact: true }).click();
  await expect(dlg).toContainText(`| ${code}`);
  await dlg.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

const placedItem = (page: Page, p: string) =>
  side(page).getByRole('listitem').filter({ hasText: p }).filter({ has: page.getByRole('button', { name: 'הסרה מהמקום' }) });

async function qtyInPlacePanel(page: Page, p: string): Promise<number> {
  const item = placedItem(page, p);
  await expect(item).toHaveCount(1);
  const n = (await item.innerText()).split('\n').map((s) => s.trim()).find((l) => /^\d+$/.test(l));
  return n === undefined ? NaN : Number(n);
}

// ---------- «החזרה לספק» ----------
async function openSupplierReturn(page: Page, p: string) {
  await openMap(page);
  await page.getByRole('button', { name: 'החזרות' }).click();
  await page.getByRole('menuitem', { name: /^החזרה לספק/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'החזרה לספק' })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'חיפוש פריט' }).fill(p);
  return dlg;
}

/** Чекбокс строки товара: «<שם> · <מק"ט> זמין N · <מקום>». */
const itemBox = (dlg: ReturnType<Page['getByRole']>, p: string, avail: number, place: string) =>
  dlg.getByRole('checkbox', { name: new RegExp(`^${p} · \\S+ זמין ${avail} · ${place}`) });

/** Поле кол-ва внутри строки (товар + место, #9301886c). */
const qtyOf = (dlg: ReturnType<Page['getByRole']>, p: string, avail: number, place: string) =>
  itemBox(dlg, p, avail, place).locator('xpath=ancestor::label[1]/parent::*').getByRole('spinbutton', { name: `כמות ל${p}` });

/** Отметить товар, ввести кол-во и ссылку, «רישום ההחזרה»; вернуть ответ rpc/return_to_supplier. */
async function submitReturn(page: Page, p: string, avail: number, place: string, qty: number, ref: string): Promise<Response> {
  const dlg = await openSupplierReturn(page, p);
  await itemBox(dlg, p, avail, place).check();
  await qtyOf(dlg, p, avail, place).fill(String(qty));
  await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(ref);
  const respP = page.waitForResponse((r) => r.url().includes('/rpc/return_to_supplier') && r.request().method() === 'POST');
  await dlg.getByRole('button', { name: 'רישום ההחזרה' }).click();
  const resp = await respP;
  expect(resp.status(), `return_to_supplier: ${await resp.text().catch(() => '')}`).toBe(200);
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
  return resp;
}

/** Тост (имя товара обёрнуто в bidi-изоляторы — поэтому `.?`). */
const toast = (page: Page, qty: number, p: string, tail: string) =>
  page.getByText(new RegExp(`^${qty} של .?${p}.? הוחזרו לספק${tail}\\.$`));

// ---------- журнал ----------
async function openJournal(page: Page, p: string) {
  await openMap(page);
  const expand = page.getByRole('button', { name: 'פתיחת יומן התנועות' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await page.getByRole('textbox', { name: 'חיפוש ביומן התנועות' }).fill(p);
}

/** Карточка журнала «החזרה לספק» с данной ссылкой (ссылка показывается как назначение). */
const returnEntry = (page: Page, ref: string) =>
  page.getByText(ref, { exact: true }).locator('xpath=ancestor::div[.//*[normalize-space()="החזרה לספק"]][1]');

async function expectReturnEntry(page: Page, ref: string, from: string, p: string, qty: number) {
  const e = returnEntry(page, ref);
  await expect(e).toHaveCount(1, { timeout: 20_000 });
  const lines = (await e.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
  expect(lines).toContain('החזרה לספק');
  expect(lines).toContain(from);
  expect(lines.some((l) => l.startsWith(`${p} · `))).toBe(true);
  expect(lines).toContain(String(qty));
  expect(lines).toContain('test admin');
}

// ---------- уборка ----------
async function deleteFromCatalog(page: Page, p: string) {
  await findProduct(page, p);
  if (!(await qtyBtn(page, p).count())) return;
  await row(page, p).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג|נמחק\./).first()).toBeVisible({ timeout: 15_000 });
}

async function cleanupAll(browser: Browser) {
  const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  try {
    if (usedPlace) {
      await openPlace(page, usedPlace);
      for (const p of created) {
        const item = placedItem(page, p);
        if (!(await item.count())) continue;
        await item.getByRole('button', { name: 'הסרה מהמקום' }).click();
        const dlg = page.getByRole('dialog');
        await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
        await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
        await expect(placedItem(page, p)).toHaveCount(0, { timeout: 15_000 });
      }
    }
    for (const p of created) await deleteFromCatalog(page, p);
    if (usedPlace) {
      const label = await openPlace(page, usedPlace);
      expect(label[label.length - 1], `${usedPlace} должно быть «ריק» после уборки`).toBe('ריק');
    }
  } finally {
    await ctx.close();
  }
}

test.describe('warehouse-map — החזרה לספק (#1f62ca42)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(240_000);
    await cleanupAll(browser);
  });

  test('החזרה לספק: כמות לא תקינה (יותר מהמלאי / 0 / ריק) חוסמת את הרישום #1f62ca42 @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    await createProduct(page, U, `QA1F62U${TS}`);
    await receive(page, U, 3, null);

    let calls = 0;
    page.on('request', (r) => { if (r.url().includes('/rpc/return_to_supplier')) calls++; });
    const dlg = await openSupplierReturn(page, U);
    await itemBox(dlg, U, 3, 'ללא שיוך למקום').check();
    const qty = qtyOf(dlg, U, 3, 'ללא שיוך למקום');
    const submit = dlg.getByRole('button', { name: 'רישום ההחזרה' });

    await qty.fill('4');
    await expect(dlg.getByText('במלאי 3 בלבד')).toBeVisible();
    await expect(qty).toHaveAttribute('aria-invalid', 'true');
    await expect(submit).toBeDisabled();

    await qty.fill('0');
    await expect(dlg.getByText('יש להזין כמות גדולה מאפס')).toBeVisible();
    await expect(submit).toBeDisabled();

    await qty.fill('');
    await expect(submit).toBeDisabled();

    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    expect(calls, 'запроса return_to_supplier быть не должно').toBe(0);
    await expectStock(page, U, 3);
  });

  test('החזרה לספק «ללא מקום»: 1 מתוך 3 ואז 2 הנותרים — מצליחה, מלאי יורד, נרשמת ביומן #1f62ca42 @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    // 1 из 3
    const r1 = await submitReturn(page, U, 3, 'ללא שיוך למקום', 1, REF('p'));
    expect(r1.request().postDataJSON()?.p_location_id ?? null).toBeNull();
    await expect(toast(page, 1, U, '')).toBeVisible({ timeout: 15_000 });
    await expectStock(page, U, 2);
    const dlg = await openSupplierReturn(page, U);
    await expect(itemBox(dlg, U, 2, 'ללא שיוך למקום')).toBeVisible({ timeout: 15_000 });
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);

    // оставшиеся 2
    const r2 = await submitReturn(page, U, 2, 'ללא שיוך למקום', 2, REF('f'));
    expect(r2.request().postDataJSON()?.p_location_id ?? null).toBeNull();
    await expect(toast(page, 2, U, '')).toBeVisible({ timeout: 15_000 });
    await expectStock(page, U, 0);
    await expect(row(page, U)).toContainText('אזל');

    // журнал: обе записи, и под «החזרות»
    await openJournal(page, U);
    await expectReturnEntry(page, REF('p'), 'ללא מקום', U, 1);
    await expectReturnEntry(page, REF('f'), 'ללא מקום', U, 2);
    const tab = page.getByRole('tablist', { name: 'סינון לפי סוג תנועה' }).getByRole('tab', { name: 'החזרות' });
    await tab.click();
    await expect(tab).toHaveAttribute('aria-selected', 'true');
    await expect(returnEntry(page, REF('p'))).toHaveCount(1);
    await expect(returnEntry(page, REF('f'))).toHaveCount(1);
  });

  test('החזרה לספק ממקום במחסן ממשיכה לעבוד — מקום וקטלוג יורדים, יומן עם המקום #1f62ca42 @desktop @data', async ({ page }) => {
    test.setTimeout(300_000);
    const place = await pickEmptyPlace(page);
    test.skip(!place, `нет пустого места из ${CANDIDATE_PLACES.join(', ')}`);
    const { code, shelf } = place!;
    usedPlace = code;

    await createProduct(page, L, `QA1F62L${TS}`);
    await bindPlace(page, L, code, shelf);
    await receive(page, L, 2, code);

    const r = await submitReturn(page, L, 2, `מדף ${code}`, 1, REF('l'));
    expect(r.request().postDataJSON()?.p_location_id ?? null).not.toBeNull();
    await expect(toast(page, 1, L, ` ממדף ${code}`)).toBeVisible({ timeout: 15_000 });
    await expectStock(page, L, 1);

    await openPlace(page, code);
    await expect.poll(() => qtyInPlacePanel(page, L), { timeout: 15_000 }).toBe(1);

    await openJournal(page, L);
    await expectReturnEntry(page, REF('l'), code, L, 1);
  });
});
